        return None
    try:
        milliseconds = int(raw)
    except ValueError as exc:
        raise DiscoveryError("invalid timeout") from exc
    if milliseconds <= 0:
        raise DiscoveryError("invalid timeout")
    return milliseconds / 1000.0


